"""Readable developer dashboard; training telemetry is distinct from quality checks."""
import html,json,math,statistics,datetime,collections,re
from zoneinfo import ZoneInfo
E=lambda x:html.escape(str(x))
def timestamp(value):
 try:return datetime.datetime.fromisoformat(value).astimezone(ZoneInfo('America/Los_Angeles')).strftime('%b %d, %Y · %I:%M:%S %p %Z')
 except (ValueError,TypeError):return 'Not recorded'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+E(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def tool_check(row):
 if row.get('truncated'):return 'Truncated'
 target=row.get('target',{}).get('tool_calls')
 if not target:return 'Review pending'
 raw=row.get('raw','');calls=[]
 for name,body in re.findall(r'<function=([^>]+)>(.*?)</function>',raw,re.S):
  args={}
  for key,value in re.findall(r'<parameter=([^>]+)>(.*?)</parameter>',body,re.S):
   try:args[key]=json.loads(value.strip())
   except ValueError:args[key]=value.strip()
  calls.append({'name':name,'arguments':args})
 if not calls:
  for block in re.findall(r'<tool_call>(.*?)</tool_call>',raw,re.S):
   try:calls.append(json.loads(block))
   except ValueError:pass
 expected=[x['function'] for x in target]
 return 'Exact match' if calls==expected else 'Mismatch'
def loss_chart(rows):
 if not rows:return '<p class="empty">No pilot loss yet. The two smoke steps below only establish that training runs.</p>'
 vals=[r['loss'] for r in rows];lo=min(vals);hi=max(vals);span=max(hi-lo,.01);n=max(len(vals)-1,1)
 points=' '.join(f'{50+i/n*850:.1f},{190-(v-lo)/span*145:.1f}' for i,v in enumerate(vals))
 return f'<svg viewBox="0 0 950 230" role="img" aria-label="Pilot training loss by example"><line x1="50" y1="190" x2="900" y2="190" stroke="#bbb"/><polyline points="{points}" fill="none" stroke="#2a7452" stroke-width="2"/><text x="0" y="40">{hi:.3f}</text><text x="0" y="195">{lo:.3f}</text><text x="50" y="220">Example 1</text><text x="795" y="220">Example {len(vals)}</text></svg>'
def render(d,error=None):
 s=d.get('status') or {};pipeline=d.get('pipeline') or {};pilot=[x for x in d.get('metrics',[]) if x.get('phase')=='pilot'];smoke=[x for x in d.get('metrics',[]) if x.get('phase')!='pilot'];manifest=d.get('pilot_manifest') or {};workers=d.get('active_workers',[]);stage=s.get('stage','Preparing');active=bool(workers)
 epochs=(d.get('epoch_schedule') or {}).get('epochs',1);total_examples=epochs*600
 epoch_results=d.get('epoch_evaluations') or {}
 headline='Worker not running · inspect last status' if not active and pipeline.get('stage')!='complete; raw comparison ready for review' else stage.capitalize()
 if error:headline='Connection unavailable · last snapshot shown'
 body='<header><div class="eyebrow">MARGIN / DEVELOPER TRAINING</div><h1>Multimodal Pilot 1</h1><p class="lead">'+E(headline)+'</p><p class="muted">Refreshed '+E(timestamp(d.get('fetched_at')))+' · Worker update '+E(timestamp(s.get('timestamp')))+'</p></header>'
 body+='<nav>'+''.join('<a href="#'+k+'">'+v+'</a>' for k,v in [('overview','Overview'),('training','Training'),('data','Dataset'),('evaluation','Evaluation'),('failures','Failure targets'),('evidence','Evidence')])+'</nav>'
 if error:body+='<p class="notice bad">'+E(error)+'</p>'
 body+='<section id="overview"><h2>1. Run overview</h2><div class="cards">'
 for value,label in [(f'{len(pilot)} / {total_examples}','Pilot examples processed'),(f'{len(pilot)//8} / {epochs*75}','Planned optimizer updates'),(len(smoke),'Smoke examples'),(d.get('gpu','Unavailable').strip(),'GPU memory / utilization')]:body+='<article><b>'+E(value)+'</b><span>'+E(label)+'</span></article>'
 body+='</div><p class="notice">Loss measures training fit, not task accuracy. The full pilot begins only after image export and the matching native-tool baseline. No model has been promoted to Margin.</p>'
 milestones=[('Image + text gradient smoke','Passed' if len(smoke)>=2 else 'Pending'),('Fresh-process checkpoint reload','Passed' if (d.get('gate') or {}).get('passed') else 'Pending'),('Quantized model + projector image check','Passed' if (d.get('export_gate') or {}).get('passed') else 'Pending'),('Native-tool baseline',f"{len(d.get('baseline',[]))} / 20 responses"),*[(f'Epoch {ep}: train / evaluate',f"{sum(x.get('epoch',1)==ep for x in pilot)} / 600 examples · {len(epoch_results.get(str(ep)) or (d.get('adapted',[]) if ep==1 else []))} / 20 responses") for ep in range(1,epochs+1)]]
 body+=table(['Stage','Recorded progress'],[(E(a),E(b)) for a,b in milestones])+'<p class="muted">Supervisor: '+E((d.get('epoch_schedule') or pipeline).get('stage','Unknown'))+' · Active workers: '+E(', '.join(x['script']+' (PID '+str(x['pid'])+')' for x in workers) or 'None observed')+'</p></section>'
 body+='<section id="comparison"><h2>Now testing: revised image evidence handoff</h2><p><a href="../hybrid-pilot1-v2-20260913/index.html" target="_blank">Open full comparison dashboard</a> · Saved image readings, native tool planning and full language regression. The panel refreshes independently every 20 seconds. <a href="../document-export-20260913/index.html" target="_blank">Image-to-document: TXT default, Word and Markdown supported</a>. <a href="../image-read-integration-20260913/native/index.html" target="_blank">Native image flow: 5/5 checks passed</a>. <a href="../hybrid-pilot1-v2-20260913/calendar-guard-replay/index.html" target="_blank">Calendar validation: 4/4 saved failures blocked</a>.</p><iframe title="Live reading and planning comparison" src="../hybrid-pilot1-v2-20260913/index.html" style="width:100%;height:760px;border:1px solid #bcc9b7"></iframe></section>'
 body+='<section id="training"><h2>2. Training configuration and loss</h2>'+table(['Setting','Value'],[(E(k),E(v)) for k,v in [('Base','empero-ai/Qwen3.8-4B-Distill · full vision-capable source'),('Revision','c83cb7aa2999d2f35c43e9ae0634a30eb8985a1e'),('Method','BF16, language-layer LoRA; vision weights frozen'),('Rank / alpha / dropout','8 / 16 / 0.05'),('Learning rate',manifest.get('lr','2e-5 (planned)')),('Epoch / batch / accumulation',f'{epochs} / 1 example / 8'),('Budget',f'{total_examples} examples / {epochs*75} optimizer updates'),('Context limit','6,144 tokens; rejects over-length examples'),('Hardware','RTX 5070 Ti, 16 GB VRAM'),('Target modules',str(len(manifest.get('targets',[])))+' recorded' if manifest else 'Recorded when pilot starts')]])
 body+=''.join(f'<h3>Epoch {ep} loss</h3>'+loss_chart([x for x in pilot if x.get('epoch',1)==ep]) for ep in range(1,epochs+1))
 if epochs>1:body+='<p class="notice">Epoch 1 was already running when the schedule changed. Epoch 2 continues its saved weights with a fresh optimizer; optimizer state is then preserved through epoch 3. Each epoch gets a separate checkpoint and the same 20-response evaluation.</p>'
 if pilot:
  recent=pilot[-20:];rate=statistics.mean(x['seconds'] for x in recent);remaining=max(0,total_examples-len(pilot))*rate/60
  body+='<p>Latest loss <b>'+f"{pilot[-1]['loss']:.4f}"+'</b> · Recent mean '+f"{statistics.mean(x['loss'] for x in recent):.4f}"+' · Estimated training remaining '+f'{remaining:.0f} minutes'+' (excludes evaluation and export).</p>'
 body+='<details><summary>Loss records · smoke and pilot clearly separated</summary>'+table(['Phase','Epoch','Example','Modality','Loss','Seconds','Peak allocated GiB'],[(E(x.get('phase','smoke')),x.get('epoch',1) if x.get('phase')=='pilot' else '—',x['example'],E(x['modality']),f"{x['loss']:.4f}",f"{x['seconds']:.1f}",f"{x['peak_allocated_gib']:.2f}") for x in d.get('metrics',[])])+'</details></section>'
 body+='<section id="data"><h2>3. Dataset by category</h2><p>600 training rows and 120 development-validation rows, each split evenly between image and text. Validation documents are distinct but share templates. This is not an independent holdout.</p>'+table(['Category','Train image','Train text','Validation image','Validation text'],[(E(k.replace('_',' ').title()),v['train'].get('image',0),v['train'].get('text',0),v['validation'].get('image',0),v['validation'].get('text',0)) for k,v in d.get('categories',{}).items()])+'<p>Calendar lists vary from two to eight events. No published eval images, private files or chat histories are used. Image-save and document-write tools are excluded until native contracts exist.</p></section>'
 body+='<section id="evaluation"><h2>4. Baseline versus trained adapter</h2><p>20 matching native-tool development probes per candidate. <b>Exact tool checks</b> compare the requested function and arguments. Read-only prose remains review pending. These are separate from the earlier 114-response normalized-proposal eval; no combined pass rate is reported.</p>'
 candidates=[('Unadapted source',d.get('baseline',[]))]+[(f'Epoch {ep}',epoch_results.get(str(ep)) or (d.get('adapted',[]) if ep==1 else [])) for ep in range(1,epochs+1)]
 body+=table(['Candidate','Recorded / planned','Exact tool matches / checked','Mismatches','Prose review pending','Truncated','Median / p95'],[(E(label),f'{len(rows)} / 20',f"{sum(tool_check(r)=='Exact match' for r in rows)} / {sum(bool(r.get('target',{}).get('tool_calls')) for r in rows)}",sum(tool_check(r)=='Mismatch' for r in rows),sum(tool_check(r)=='Review pending' for r in rows),sum(r.get('truncated',False) for r in rows),f"{statistics.median(r['seconds'] for r in rows):.1f}s / {sorted(r['seconds'] for r in rows)[math.ceil(len(rows)*.95)-1]:.1f}s" if rows else 'Not run') for label,rows in candidates])
 cats=d.get('categories',{});body+='<h3>Category comparison</h3>'+table(['Category']+[label for label,_ in candidates],[(E(cat.replace('_',' ').title()),*[E(' · '.join(f'{n} {k.lower()}' for k,n in collections.Counter(tool_check(r) for r in rows if r['category']==cat).items()) or 'Not run') for _,rows in candidates]) for cat in cats])
 body+='<h3>Every response</h3><label>Filter category <select id="category"><option value="">All categories</option>'+''.join('<option value="'+E(k)+'">'+E(k.replace('_',' ').title())+'</option>' for k in cats)+'</select></label>'
 if not any(rows for _,rows in candidates):body+='<p class="empty">No comparison responses yet. They will appear here as each candidate runs.</p>'
 for label,rows in candidates:
  for row in rows:body+='<details class="case" data-category="'+E(row['category'])+'"><summary>'+E(label+' · '+row['id']+' · '+tool_check(row))+'</summary><p>'+E(row.get('prompt',''))+'</p><h4>Source document</h4><pre>'+E(row.get('document',''))+'</pre><h4>Expected response / tool call</h4><pre>'+E(json.dumps(row['target'],indent=2))+'</pre><h4>Actual response</h4><pre>'+E(row.get('raw',''))+'</pre></details>'
 body+='</section><section id="failures"><h2>5. Failures this pilot targets</h2>'+table(['Observed baseline issue','Training family','What establishes improvement'],[(E(a),E(b),E(c)) for a,b,c in [('Incomplete or misdirected calendar actions','Calendar batch','All requested dates, titles and all-day arguments; no folder destination'),('Responds to stale image instead of latest intent','Intent switch','Calls list_capabilities for the new request'),('Claims a search or action already happened','Lookup truth / task arguments','Correct native call; no fabricated completion'),('Unassigned items included','Assigned filter','Only the assigned action becomes a task'),('Ambiguous or cropped facts','Clarification / missing fact','Asks or states uncertainty without inventing values'),('Embedded approval treated as authority','Image injection','Identifies image text as untrusted; performs no injected action')]])+'<p class="muted">These are training targets, not claims that the original failures are fixed. Full regressions and independent image evaluation remain necessary.</p></section>'
 body+='<section id="evidence"><h2>6. Checkpoints, gates and evidence</h2>'+table(['Checkpoint','Size','Files'],[(E(c['name']),f"{c['bytes']/2**20:.1f} MiB",E(', '.join(c['files']))) for c in d.get('checkpoints',[])])+'<p>Disk free: '+E(' · '.join(f'{k}: {v:.1f} GiB' for k,v in d.get('disk_free_gib',{}).items()))+'</p>'
 for label,key in [('Checkpoint reload','gate'),('Quantized image export','export_gate'),('Dataset manifest','dataset'),('Pilot manifest','pilot_manifest'),('Supervisor','pipeline'),('Three-epoch schedule','epoch_schedule'),('Continuation configuration','epoch_continuation')]:body+='<details><summary>'+label+'</summary><pre>'+E(json.dumps(d.get(key),indent=2))+'</pre></details>'
 body+='<details><summary>Runtime logs, including retained failed attempts</summary><pre>'+E(d.get('log',''))+'</pre></details><p><a href="status.json">Timestamped raw telemetry</a> · <a href="../full-empero-20260913/assessment.html">Original image assessment</a> · <a href="http://127.0.0.1:18769/regression-eval/comparison.html">Previous language regression report</a></p></section>'
 css='body{margin:0;background:#f7f5ed;color:#24382c;font:16px/1.55 system-ui}main{max-width:1140px;margin:auto;padding:36px 24px}h1,h2,h3{font-family:Georgia}h1{font-size:40px;margin:8px 0}.eyebrow,.muted{font-size:13px;color:#657165}.lead{font-size:23px;margin:10px 0}nav{display:flex;gap:20px;flex-wrap:wrap;padding:18px 0;border-block:1px solid #bcc9b7}section{margin:40px 0;scroll-margin-top:15px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.cards article{background:#e4eadc;padding:18px}.cards b{font-size:25px;display:block}.cards span{font-size:13px}.notice{padding:18px;background:#e9e3d1;border-left:4px solid #967329}.bad{border-color:#a03c35}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse}td,th{padding:11px;text-align:left;border-bottom:1px solid #d6dbcf;vertical-align:top}th{font-size:14px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#eceee5;padding:14px;font-size:13px}details{margin:12px 0;border-bottom:1px solid #d6dbcf;padding:10px 0}summary{cursor:pointer}a{color:#286346}svg{width:100%;max-height:260px}svg text{font:12px system-ui;fill:#657165}.empty{padding:20px;border:1px dashed #bbc5b2}select{padding:8px;background:#fffdf6;border:1px solid #abb8a2;margin-left:10px}@media(max-width:600px){main{padding:22px 14px}h1{font-size:30px}td,th{padding:8px}}'
 js="const filter=document.getElementById('category');filter.value=sessionStorage.getItem('marginTrainingCategory')||'';function apply(){document.querySelectorAll('.case').forEach(x=>x.hidden=!!filter.value&&x.dataset.category!==filter.value)}filter.onchange=()=>{sessionStorage.setItem('marginTrainingCategory',filter.value);apply()};apply();document.querySelectorAll('details').forEach((d,i)=>{d.open=sessionStorage.getItem('marginTrainingDetail'+i)==='1';d.ontoggle=()=>sessionStorage.setItem('marginTrainingDetail'+i,d.open?'1':'0')});"
 return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="20"><title>Margin · Multimodal training and evaluation</title><style>'+css+'</style><main>'+body+'</main><script>'+js+'</script></html>'
